import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Router, ActivatedRoute } from '@angular/router';
import { AuthService } from '../../services/auth.service';

@Component({
  selector: 'app-login',
  templateUrl: './login.component.html',
  styleUrls: ['./login.component.css']
})
export class LoginComponent implements OnInit {
  loginForm!: FormGroup;
  isSubmitting = false;
  errorMsg = '';
  returnUrl = '/dashboard';

  constructor(
    private fb: FormBuilder,
    private authService: AuthService,
    private router: Router,
    private route: ActivatedRoute
  ) {}

  ngOnInit(): void {
    this.loginForm = this.fb.group({
      email: ['john.miller@example.com', [Validators.required, Validators.email]],
      password: ['password123', Validators.required]
    });
    this.returnUrl = this.route.snapshot.queryParams['returnUrl'] || '/dashboard';
  }

  onSubmit(): void {
    if (this.loginForm.invalid) return;

    this.isSubmitting = true;
    this.errorMsg = '';
    this.authService.login(this.loginForm.value).subscribe({
      next: () => {
        this.isSubmitting = false;
        this.router.navigateByUrl(this.returnUrl);
      },
      error: (err) => {
        this.isSubmitting = false;
        this.errorMsg = err.error?.message || 'Login failed. Invalid credentials.';
      }
    });
  }
}
<div class="container page-container">
  <div class="auth-card">
    <div class="auth-header">
      <h2>Passenger Portal Login</h2>
      <p>Sign in to access flight reservations, baggage telemetry, and boarding passes.</p>
    </div>

    <div *ngIf="errorMsg" class="alert-error">{{ errorMsg }}</div>

    <form [formGroup]="loginForm" (ngSubmit)="onSubmit()">
      <div class="form-group">
        <label class="form-label">Email Address</label>
        <input type="email" class="form-control" formControlName="email" />
      </div>

      <div class="form-group">
        <label class="form-label">Password</label>
        <input type="password" class="form-control" formControlName="password" />
      </div>

      <div class="demo-tip">
        <strong>Demo Credentials Pre-filled:</strong><br>
        Email: <code>john.miller@example.com</code> / Password: <code>password123</code>
      </div>

      <button type="submit" class="btn btn-primary btn-block" [disabled]="isSubmitting">
        {{ isSubmitting ? 'Signing In...' : 'Sign In to Portal' }}
      </button>
    </form>

    <div class="auth-footer">
      Don't have an account? <a routerLink="/register">Register here</a>
    </div>
  </div>
</div>
